requirements=[];section=0;ordinal=0;current=None
for line in plan.split('## Implementation notes')[0].splitlines():
 m=re.match(r'## (\d+)\.',line)
 if m:section=int(m[1]);ordinal=0;current=None
 if re.match(r'- \[[ x]\]',line):
  ordinal+=1;current=None
  if line.startswith('- [ ]'):
   current={'id':f'{section}.{ordinal}','requirement':line[6:]};requirements.append(current)
 elif current and line.startswith('      '):current['requirement']+=' '+line.strip()
